let deleteId=null,dashboardYear=String(new Date().getFullYear());
function activeRecords(){return records.filter(r=>!r.deletedAt);}
function createdParts(r){const d=new Date(r.createdAt);if(!Number.isFinite(d.getTime()))return null;const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit'}).formatToParts(d);return {year:parts.find(p=>p.type==='year').value,month:Number(parts.find(p=>p.type==='month').value)-1};}
function contractAmount(r){const n=numeric(r.values.total_amount);return n!==null&&n>=0?n:null;}
function compactAmount(n){if(n>=100000000)return +(n/100000000).toFixed(1)+'억';if(n>=10000)return +(n/10000).toFixed(1)+'만';return n.toLocaleString('ko-KR');}
function renderDashboard(){const all=activeRecords(),years=[...new Set([String(new Date().getFullYear()),...all.map(r=>createdParts(r)?.year).filter(Boolean)])].sort().reverse();if(!years.includes(dashboardYear))dashboardYear=years[0];$('#dashboardYear').innerHTML=years.map(y=>`<option value="${y}" ${y===dashboardYear?'selected':''}>${y}년</option>`).join('');const selected=all.filter(r=>createdParts(r)?.year===dashboardYear),registered=selected.filter(r=>r.status==='registered'),valued=registered.filter(r=>contractAmount(r)!==null),drafts=selected.length-registered.length,total=valued.reduce((s,r)=>s+contractAmount(r),0),supply=registered.reduce((s,r)=>s+(numeric(r.values.supply_amount)??0),0),vat=registered.reduce((s,r)=>s+(numeric(r.values.vat_amount)??0),0);
 $('#dashTotal').innerHTML=esc(total.toLocaleString('ko-KR'))+'<span>원</span>';$('#dashSupply').textContent=money(supply);$('#dashVat').textContent=money(vat);$('#dashYearLabel').textContent=dashboardYear+'년 작성 건';$('#dashRegisteredCount').textContent=registered.length+'건 등록 완료';$('#dashDraftCount').innerHTML=drafts+'<small>건</small>';$('#dashAllCount').textContent=selected.length;
 const monthly=Array(12).fill(0),counts=Array(12).fill(0);valued.forEach(r=>{const m=createdParts(r).month;monthly[m]+=contractAmount(r);counts[m]++;});const max=Math.max(...monthly,1),step=Math.pow(10,Math.floor(Math.log10(max)))*.5,axisMax=Math.ceil(max/step)*step,peak=monthly.indexOf(Math.max(...monthly));const W=580,H=265,left=48,top=20,bottom=225,chartW=518,chartH=205,slot=chartW/12,barW=25;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${dashboardYear}년 월별 계약금액 막대그래프"><defs><pattern id="barHatch" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><path d="M0 0v5" stroke="#148358" stroke-opacity=".2" stroke-width="1.5"/></pattern></defs>`;for(let i=0;i<=4;i++){const y=bottom-chartH*i/4;svg+=`<line x1="${left}" y1="${y}" x2="${left+chartW}" y2="${y}" stroke="#e9eeea" stroke-dasharray="4 5"/><text x="${left-10}" y="${y+3}" text-anchor="end" fill="#9ba79e" font-size="9">${compactAmount(axisMax*i/4)}</text>`;}monthly.forEach((n,i)=>{const height=n/axisMax*chartH,x=left+i*slot+(slot-barW)/2,y=bottom-height;svg+=`<g tabindex="0" role="img" aria-label="${i+1}월 ${esc(money(n))}, ${counts[i]}건"><title>${i+1}월 · ${money(n)} · 등록 ${counts[i]}건</title><rect x="${x}" y="${y}" width="${barW}" height="${height}" rx="${Math.min(12,height/2)}" fill="${i===peak&&n>0?'#12895c':'#b7d7c7'}"/><rect x="${x}" y="${y}" width="${barW}" height="${height}" rx="${Math.min(12,height/2)}" fill="url(#barHatch)"/><text x="${x+barW/2}" y="${bottom+22}" text-anchor="middle" fill="#8e9b93" font-size="10">${i+1}월</text></g>`;});svg+='</svg>';$('#monthlyChart').innerHTML=svg+(total===0?'<span class="chart-empty">집계할 등록 완료 계약금액이 없습니다.</span>':'');$('#monthlyTotal').textContent='연간 합계 '+money(total);
 const pct=selected.length?Math.round(registered.length/selected.length*100):0;$('#statusDonut').style.background=selected.length?`conic-gradient(#12895c 0 ${registered.length/selected.length*100}%,#e3ece6 0)`:'#eef1ef';$('#statusLegend').innerHTML=`<div><i></i><span>등록 완료</span><strong>${registered.length}건</strong></div><div><i class="pale"></i><span>작성 중</span><strong>${drafts}건</strong></div><p>등록 완료 비율 <b>${pct}%</b></p>`;const excel=selected.filter(r=>r.method==='excel').length;$('#methodBars').innerHTML=[['직접 입력',selected.length-excel],['DOX AI 연결',excel]].map(([label,n])=>`<div><span>${label}</span><div class="method-track"><i style="width:${selected.length?n/selected.length*100:0}%"></i></div><b>${n}</b></div>`).join('');
 const vendors=new Map();valued.forEach(r=>{const name=r.values.supplier_name?.trim()||'공급업체 미입력';vendors.set(name,(vendors.get(name)||0)+contractAmount(r));});const rankings=[...vendors].sort((a,b)=>b[1]-a[1]).slice(0,5),vendorMax=Math.max(...rankings.map(v=>v[1]),1);$('#vendorChart').innerHTML=rankings.length?rankings.map(([name,n],i)=>`<div class="vendor-row" title="${esc(name)} · ${esc(money(n))}"><div><span class="vendor-rank">${String(i+1).padStart(2,'0')}</span><span>${esc(name)}</span><strong>${esc(compactAmount(n))}원</strong></div><div class="vendor-track"><i style="width:${n/vendorMax*100}%"></i></div></div>`).join(''):'<div class="dash-empty">등록된 공급업체 계약금액이 없습니다.</div>';$('#vendorNote').textContent='계약 공급업체 '+vendors.size+'개 · VAT 포함';
 const recent=[...selected].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,5);$('#recentBody').innerHTML=recent.length?recent.map(r=>`<tr><td><span class="recent-symbol">${r.method==='excel'?'▧':'✎'}</span><div><button data-recent="${r.id}">${esc(r.title)}</button><small>${esc(r.values.supplier_name||'공급업체 미입력')}</small></div></td><td>${esc(time(r.updatedAt))}</td><td><span class="recent-status ${r.status==='registered'?'done':''}"><i></i>${r.status==='registered'?'등록 완료':'작성 중'}</span></td><td>${esc(money(r.values.total_amount))}</td></tr>`).join(''):'<tr><td colspan="4" class="dash-empty">선택한 연도에 저장된 업무가 없습니다.</td></tr>';$('#recentBody').querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>navigate('#case/'+b.dataset.recent));const demoCount=selected.filter(r=>r.isDemo).length;const invalid=registered.length-valued.length;$('.dashboard-note').textContent=`지표는 ${dashboardYear}년 생성된 업무 건을 기준으로 계산합니다. 금액은 지급액이 아닌 계약금액입니다.${demoCount?' 시연용 더미 '+demoCount+'건이 포함되어 있습니다.':''}${invalid?' 금액이 누락되거나 유효하지 않은 등록 완료 '+invalid+'건은 계약금액 집계에서 제외했습니다.':''}`;
}
function askDelete(id){const r=records.find(r=>r.id===id&&!r.deletedAt);if(!r)return;deleteId=id;$('#deleteTitle').textContent=r.title;$('#deleteDialog .import-note').innerHTML=dirty&&draft?.id===id?'저장된 건을 휴지통으로 이동하고 현재 수정 중인 내용은 버립니다.<br>저장되어 있던 정보는 휴지통에서 복원할 수 있습니다.':'목록과 대시보드에서 제외하고 휴지통으로 이동합니다.<br>휴지통에서 다시 복원할 수 있습니다.';$('#deleteDialog').showModal();}
function confirmDelete(){const r=records.find(r=>r.id===deleteId&&!r.deletedAt);if(!r)return;clearTimeout(saveTimer);const next=records.map(x=>x.id===deleteId?{...x,deletedAt:new Date().toISOString()}:x);if(!storeData(next,draft?.id===deleteId?null:draft))return toast('브라우저에 삭제 상태를 저장하지 못했습니다.');records=next;$('#deleteDialog').close();if(draft?.id===deleteId){dirty=false;draft=null;applyRoute('#cases');}else{renderList();renderDashboard();}deleteId=null;toast('휴지통으로 이동했습니다. 휴지통에서 복원할 수 있습니다.');}
function renderTrash(){const deleted=records.filter(r=>r.deletedAt).sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));$('#trashBody').innerHTML=deleted.length?deleted.map(r=>`<div class="trash-item"><div><strong>${esc(r.title)}</strong><p>${esc(number(r))} · 삭제일 ${esc(time(r.deletedAt))}</p></div><button class="button secondary" data-restore="${r.id}">복원</button></div>`).join(''):'<div class="dash-empty">휴지통이 비어 있습니다.</div>';$('#trashBody').querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const next=records.map(r=>r.id===b.dataset.restore?{...r,deletedAt:null}:r);if(!storeData(next))return toast('복원 내용을 저장하지 못했습니다.');records=next;renderTrash();renderList();renderDashboard();toast('업무 건을 복원했습니다.');});}
function openTrash(){renderTrash();$('#trashDialog').showModal();}
function dashboardList(status='all'){$('#listSearch').value='';$('#statusFilter').value=status;$('#methodFilter').value='all';navigate('#cases');}
$('#navHome').onclick=()=>navigate('#dashboard');document.querySelectorAll('.rail [data-route]').forEach(b=>b.onclick=()=>navigate(b.dataset.route));$('#dashboardYear').onchange=e=>{dashboardYear=e.target.value;renderDashboard();};$('#dashboardList').onclick=()=>dashboardList();$('#recentAll').onclick=()=>dashboardList();$('#dashboardDrafts').onclick=()=>dashboardList('draft');$('#openTrash').onclick=openTrash;$('#railTrash').onclick=openTrash;$('#closeTrash').onclick=()=>$('#trashDialog').close();$('#cancelDelete').onclick=()=>$('#deleteDialog').close();$('#confirmDelete').onclick=confirmDelete;$('#deleteDetail').onclick=()=>askDelete(draft?.id);
init();
